3	// bracketIndex returns the index of the first limit that v is strictly below.
4	//
5	// Limits are EXCLUSIVE upper bounds and must be sorted ascending: with limits
6	// {100, 500}, v=99 is in bracket 0, v=100 and v=499 are in bracket 1, and
7	// v=500 or more returns len(limits) ("above every bracket").
8	//
9	// Callers that depend on the exclusive bounds, do not change them:
10	//   - InsuranceFee (insurance.go): the carrier's cover bands are "under $100",
11	//     "under $500", ..., so a declared value of exactly $100.00 is in band 1.
12	//   - OversizeFee (surcharges.go): the carrier counts a parcel whose length
13	//     plus girth is exactly 300 cm as oversize.
14	//
15	// If you need inclusive ("up to and including") limits, convert them at the
16	// call site instead of changing this function.
17	func bracketIndex(limits []int, v int) int {
18		for i, limit := range limits {
19			if v < limit {
20				return i
21			}
22		}
23		return len(limits)
24	}
